package com.adent.odontogram.domain;
import com.adent.shared.domain.BaseEntity; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="odontogram_entries") public class OdontogramEntry extends BaseEntity {
 @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(name="odontogram_id",nullable=false) private UUID odontogramId; @Column(name="tooth_code",nullable=false,length=10) private String toothCode; @Column(name="surface_code",length=10) private String surfaceCode; @Column(name="condition_code",nullable=false,length=50) private String conditionCode; @Column(length=180) private String diagnosis; @Column(length=180) private String treatment; @Column(name="entry_status",length=40) private String entryStatus; @Column(length=20) private String color; @Column(columnDefinition="text") private String notes;
 public UUID getTenantId(){return tenantId;}public void setTenantId(UUID v){tenantId=v;}public UUID getOdontogramId(){return odontogramId;}public void setOdontogramId(UUID v){odontogramId=v;}public String getToothCode(){return toothCode;}public void setToothCode(String v){toothCode=v;}public String getSurfaceCode(){return surfaceCode;}public void setSurfaceCode(String v){surfaceCode=v;}public String getConditionCode(){return conditionCode;}public void setConditionCode(String v){conditionCode=v;}public String getDiagnosis(){return diagnosis;}public void setDiagnosis(String v){diagnosis=v;}public String getTreatment(){return treatment;}public void setTreatment(String v){treatment=v;}public String getEntryStatus(){return entryStatus;}public void setEntryStatus(String v){entryStatus=v;}public String getColor(){return color;}public void setColor(String v){color=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}
}
